import fs from 'fs';
import path from 'path';
import { Deck } from './types';

// Ruta absoluta a nuestra nueva carpeta de base de datos local
const decksDirectory = path.join(process.cwd(), 'data', 'decks');

// 1. Función para obtener TODOS los mazos (La usaremos en la página principal para el catálogo)
export function getAllDecks(): Deck[] {
  try {
    // Leemos todos los nombres de archivo dentro de data/decks/
    const fileNames = fs.readdirSync(decksDirectory);
    
    const decks = fileNames
      .filter((fileName) => fileName.endsWith('.json'))
      .map((fileName) => {
        // Leemos el contenido de cada archivo .json
        const fullPath = path.join(decksDirectory, fileName);
        const fileContents = fs.readFileSync(fullPath, 'utf8');
        
        // Lo convertimos a un objeto TypeScript
        return JSON.parse(fileContents) as Deck;
      });

    return decks;
  } catch (error) {
    console.error("Error leyendo los mazos:", error);
    return [];
  }
}

// 2. Función para obtener un ÚNICO mazo por su ID (La usaremos para las URLs dinámicas como /deck/blood-rites)
export function getDeckById(id: string): Deck | null {
  try {
    const fullPath = path.join(decksDirectory, `${id}.json`);
    const fileContents = fs.readFileSync(fullPath, 'utf8');
    return JSON.parse(fileContents) as Deck;
  } catch (error) {
    // Si el archivo no existe (ej: el usuario inventa una URL), devolvemos null de forma segura
    return null;
  }
}