import React from 'react';
import Header from '../components/Header';
import DeckCatalogCard from '../components/DeckCatalogCard';
import { getAllDecks } from '../lib/dataLoader';

// Esta línea le indica a Next.js que esta página debe actualizarse si cambian los archivos locales
export const dynamic = 'force-dynamic';

export default function Home() {
  // Cargamos todos los mazos usando nuestro nuevo motor de datos local
  const decks = getAllDecks();

  return (
    <>
      <Header />
      <main className="flex flex-col items-center justify-start p-4 md:p-8 lg:p-12 max-w-7xl mx-auto w-full">
        
        {/* Cabecera hero de la página */}
        <div className="text-center mb-12 mt-6">
          <h1 className="text-4xl md:text-6xl font-extrabold text-white mb-6 tracking-tight">
            Mejora tu Mazo Preconstruido
          </h1>
          <p className="text-gray-400 text-lg md:text-xl max-w-3xl mx-auto">
            Selecciona tu mazo para descubrir la guía definitiva de mejoras. Te mostramos qué cartas añadir y quitar con precios actualizados en tiempo real.
          </p>
        </div>

        {/* Grid del Catálogo de Mazos */}
        <div className="w-full grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6 md:gap-8">
          {decks.length > 0 ? (
            decks.map((deck) => (
              <DeckCatalogCard 
                key={deck.id}
                id={deck.id}
                name={deck.name}
                image={deck.image}
                commander={deck.commander}
              />
            ))
          ) : (
            <div className="col-span-full text-center p-12 border-2 border-dashed border-surfaceHover rounded-2xl">
              <p className="text-gray-400 text-lg">No hay mazos disponibles.</p>
              <p className="text-sm text-gray-500 mt-2">Añade archivos .json en la carpeta data/decks/</p>
            </div>
          )}
        </div>
        
      </main>
    </>
  );
}